				TensionID prevTentionID = playerData.tension;
				float skillEndTime = elapsedTime + player.SkillAnimDuration;
				ContestUtils.EmitLog(string.Format("Start ContestSkill : Player{0} : Start {1} : End {2} : Note Index {3}", playerIndex, elapsedTime, skillEndTime, playerData.currentNoteDataIndex));
				PlayerDanceDataModel afterData = CalcScoreAfterContestWaza(player, skillEndTime);
				ContestUtils.EmitLog(string.Format("Finish Check AutoSuccess Note : Index {0}", afterData.currentNoteDataIndex));

				Coroutine coroutine = null;
				coroutine = SmartPoint.AssetAssistant.Sequencer.Start(IE_DoActivePlayerSkillAnimation(player, () =>
				{
					playerData.SetPlayerData(afterData);
					if (player.PlayerType == PlayerType.User)
						notesLane.SetHeartGaugeRatio(dataModel.GetHeartGaugeRatio());

					playerData.FinishedSkillAnim();
					if (prevTentionID == playerData.tension)
						uiPlayerStatus.SetTensionID(playerIndex, prevTentionID);
					else
						uiPlayerStatus.SetTensionID(playerIndex, playerData.tension, playerData.tension < prevTentionID);

					// CheckSkillComboBonus (no bl to it anywhere; placed after this lambda's first-level callees) inlined
					CheckSkillComboBonus(playerIndex);
					EmitHeart(playerIndex, player.PlayerType);
				}, () =>
				{
					player.ActivateSkillEffect(elapsedTime, () => uiPlayerStatus.OnFinishedSkillEffect(playerIndex));
					runningCoroutineList.Remove(coroutine);
				}));
				runningCoroutineList.Add(coroutine);
			}
			else
			{
				playerData.FinishedSkillAnim();
				EmitHeart(playerIndex, player.PlayerType);

				Coroutine coroutine = null;
				// IE_DoNonActivePlayerSkillAnimation's factory inlined (its own flag 0x4cbe444 @01d87bdc)
				coroutine = SmartPoint.AssetAssistant.Sequencer.Start(IE_DoNonActivePlayerSkillAnimation(player.SkillAnimDuration, () =>
				{
					player.ActivateSkillEffect(elapsedTime, () => uiPlayerStatus.OnFinishedSkillEffect(playerIndex));
					runningCoroutineList.Remove(coroutine);
				}));
				runningCoroutineList.Add(coroutine);
			}
		}
		private void ShowSkillUI(global::Dpr.Contest.ADancePlayer player, bool isPrevSameWazaType, bool isSameUserWazaType) {
			// IsShowChainCount inlined (bounds check on comboBonusDataArray @01d88d64)
			uiSkillInfo.UseContestSkill(player.PlayerIndex, dataModel.ChainCount, dataModel.IsShowChainCount(), dataModel.CanUpdateAcceptChain, isPrevSameWazaType, isSameUserWazaType);
			uiPlayerStatus.LaunchContestWaza(player.PlayerIndex);
			if (player.PlayerType != PlayerType.User && !dataModel.IsAlreadyUseUserSkill)
				uiSkillInfo.PlayCommandAppealTween();
		}
		private global::System.Collections.IEnumerator IE_DoActivePlayerSkillAnimation(global::Dpr.Contest.ADancePlayer player, global::System.Action onFinishAnim, global::System.Action onComplete) {
			// state table @03d5bdff: 0 -> entry, 1/2 -> the wait loop, 3, 4, 5 (Roslyn numbers the yields in source order)
			if (player.PlayerType == PlayerType.User)
			{
				// SetBGMVolumeRatio inlined (StartBGMFade stores @01d8adb8)
				ContestSoundPlayer.player.SetBGMVolumeRatio(dataModel.DownVolumePersent);
				wazaSeqPlayer.PlayWazaSequence(player.PlayerIndex);
				notesLane.DoPlayUIFadeTween(false);
				// IsLongTap (flag 0x4cbe454), StopSE (0x4cbe424) and FinishLongTap inlined
				if (dataModel.IsLongTap)
				{
					ContestSoundPlayer.player.StopSE(ContestSoundPlayer.StopSE_ID.TapLong);
					notesLane.DeactiveHoldFx();
					dataModel.FinishLongTap();
				}

				yield return waitUIFadeTween;

				while (wazaSeqPlayer.IsRunning)
					yield return null;

				// ResetBGMVolume inlined (flag 0x4cbe41f, PlayerWork.config.bgm_volume / 10f @01d8acbc)
				ContestSoundPlayer.player.ResetBGMVolume();
				notesLane.DoPlayUIFadeTween(true);
				ContestUtils.EmitLog(string.Format("Finish Skill Animation : {0}", elapsedTime));
				onFinishAnim?.Invoke();
			}
			else
			{
				yield return waitUIFadeTween;
				yield return new WaitForSeconds(player.SkillAnimDuration);
				onFinishAnim?.Invoke();
			}

			yield return waitUserWazaAfter;
			onComplete?.Invoke();
		}
		private global::System.Collections.IEnumerator IE_DoNonActivePlayerSkillAnimation(float duration, global::System.Action onComplete) {
			yield return new WaitForSeconds(duration);
			yield return waitUserWazaAfter;
			onComplete?.Invoke();
		}
		private global::Dpr.Contest.PlayerDanceDataModel CalcScoreAfterContestWaza(global::Dpr.Contest.ADancePlayer player, float checkElapsedTime) {
			if (player.PlayerType == PlayerType.User)
				notesLane.HideNotesUntilTime(checkElapsedTime);

			// GetPlayerDanceDataByIndex inlined (@01d88ee8)
			PlayerDanceDataModel result = dataModel.CalcPlayerScoreAfterContestWaza(dataModel.GetPlayerDanceDataByIndex(player.PlayerIndex), elapsedTime, checkElapsedTime, player.PlayerType == PlayerType.User);
			if (player.PlayerType == PlayerType.User && dataModel.LastNoteData != null && dataModel.LastNoteData.notesType == NoteTypeID.LongEnd)
				notesLane.DeactiveNotesBg(dataModel.LastNoteData.id);

			return result;
		}
		private void CheckSkillComboBonus(int playerIndex) {
			if (dataModel.LastUsePlayerIndex == playerIndex && !dataModel.CanUpdateAcceptChain)
			{
				dataModel.ApplyScoreBonus();
				for (int i = 0; i < dancePlayerArray.Length; i++)
					EmitHeart(i, dancePlayerArray[i].PlayerType);
			}
		}
		private void UpdateUI() {
			notesLane.OnUpdate(elapsedTime);
			scoreGauge.OnUpdate(deltaTime);
			uiSkillInfo.OnUpdate(deltaTime);
			// UpdateProgressGauge / UpdateChainGauge inlined (identical blocks @01d86378 / @01d863f0), CheckCreateNote = tail call
			UpdateProgressGauge();
			UpdateEmitHeart(deltaTime);
			UpdateChainGauge();
			CheckCreateNote();
		}
		private void UpdateProgressGauge() {
			if (!uiMusicProgress.IsActive)
				return;

			// CanUpdateProgressGauge inlined (placed right after UpdateChainGauge, @01d89a80)
			if (dataModel.CanUpdateProgressGauge(elapsedTime, out float gaugeRatio) && !uiMusicProgress.IsMoveEnd)
			{
				// fcmp ratio, 1 ; b.lt skip (@01d89744): NaN skips
				if (gaugeRatio >= 1f)
					uiMusicProgress.FinishIconMove();

				uiMusicProgress.OnUpdate(elapsedTime, gaugeRatio);
			}
		}
		private void EmitHeart(int playerIndex, global::Dpr.Contest.PlayerType playerType) {
			if (lockEmitHeartFlag)
				return;

			// CanEmitHeartByPlayerIndex inlined (@01d88524)
			if (!dataModel.CanEmitHeartByPlayerIndex(playerIndex))
				return;

			Vector3 fromPos = Vector3.zero;
			if (playerType == PlayerType.User)
				fromPos = notesLane.TapIconCenterPos;
			else
				fromPos = uiPlayerStatus.GetIconPos(playerIndex);

			while (dataModel.ApplyTotalScoreFromPlayer(playerIndex, out ApplyScoreResult result))
			{
				EmitHeartData data = new EmitHeartData();
				data.playerType = playerType;
				data.pattern = result.pattern;
				data.from = fromPos;
				data.to = scoreGauge.MarkCenterPos;
				data.liveGaugeRatio = result.gaugeRatio;
				emitHeartDataQueue.Enqueue(data);
			}
		}
		private void UpdateEmitHeart(float deltaTime) {
			// the closure (DisplayClass73_0 {this, data}) is allocated at method entry: `data` is a method-scope local
			if (lockEmitHeartFlag || emitHeartDataQueue.Count <= 0 || !waitEmitHeartTimer.IsFinishWait(deltaTime))
				return;

			waitEmitHeartTimer.ResetTimer();
			EmitHeartData data = emitHeartDataQueue.Dequeue();
			DanceHeartEffect heart;
			if (data.playerType == PlayerType.User)
			{
				// PlaySeByID inlined (flag 0x4cbe421 @01d89910)
				ContestSoundPlayer.player.PlaySeByID(ContestSoundPlayer.PlaySE_ID.PointHeart);
				heart = manager.CreatePlayerHeart(data.from, data.to, data.pattern, () => scoreGauge.SetScoreRatio(data.liveGaugeRatio, data.pattern));
			}
			else
			{
				heart = manager.CreateNPCHeart(data.from, data.to, data.pattern, () => scoreGauge.SetScoreRatio(data.liveGaugeRatio, data.pattern));
			}

			activeDanceHeartList.Add(heart);
		}
		private void UpdateChainGauge() {
			if (!dataModel.CanUpdateAcceptChain)
				return;

			// CalcChaniGaugeRatio inlined (@01d89a0c)
			float ratio = dataModel.CalcChaniGaugeRatio(elapsedTime);
			uiSkillInfo.UpdateChainGauge(ratio);
			// fcmp ratio, 1 ; b.mi return (@01d89a58): NaN applies the bonus
			if (ratio < 1f)
				return;

			dataModel.ApplyScoreBonus();
		}
		private void UpdateHeartEffect() {
			int i = 0;
			while (i < activeDanceHeartList.Count)
			{
				DanceHeartEffect heart = activeDanceHeartList[i];
				if (heart != null)
				{
					// DanceHeartEffect.OnUpdate inlined (isPlayerHeart test @01d8652c)
					heart.OnUpdate(deltaTime);
					if (heart.IsActive)
					{
						i++;
						continue;
					}
				}

				activeDanceHeartList.RemoveAt(i);
			}
		}
		public void OnLateUpdate() {
			wazaSeqPlayer.OnLateUpdate();
		}
		private void DoPlayAllTween(bool forward) {
			if (forward)
				uiDanceFadeTween.DOPlayForward();
			else
				uiDanceFadeTween.DOPlayBackwards();

			notesLane.DoPlayUIFadeTween(forward);
		}
		private void DoPlayUIDanceTween(bool forward) {
			if (forward)
				uiDanceFadeTween.DOPlayForward();
			else
				uiDanceFadeTween.DOPlayBackwards();
		}
		public void OnLeaveOtherPlayer(int index) {
			if (dancePlayerArray == null)
				return;

			ADancePlayer player = dancePlayerArray[index];
			switch (player.PlayerType)
			{
				case PlayerType.NPC:
				{
					DanceNPC npc = player as DanceNPC;
					if (npc != null && active && !npc.IsActive)
						npc.Activate();

					break;
				}
				case PlayerType.Other:
				{
					DanceOtherUser otherUser = player as DanceOtherUser;
					if (otherUser != null)
						otherUser.SwitchUserToNPC(elapsedTime);

					break;
				}
			}
		}
		public void OnChangeHostMine() {
			foreach (ADancePlayer player in dancePlayerArray)
			{
				switch (player.PlayerType)
				{
					case PlayerType.NPC:
					{
						DanceNPC npc = player as DanceNPC;
						if (npc != null)
						{
							// SkipCurrentNotesIndexByTime inlined (its own flag 0x4cbe434 @01d89ee4)
							npc.SkipCurrentNotesIndexByTime(elapsedTime);
							npc.Activate();
						}

						break;
					}
					case PlayerType.Other:
						player.DeActivate();
						break;
				}
			}
		}
		private void SendScoreData(global::Dpr.Contest.ADancePlayer player) {
			if (!CheckCanSendPacket(player))
				return;

			// GetPlayerDanceDataByIndex inlined (one bounds check @01d871dc)
			PlayerDanceDataModel danceData = dataModel.GetPlayerDanceDataByIndex(player.PlayerIndex);
			network.SendScoreDataToAll(player.PlayerIndex, danceData.totalDanceScore, (int)danceData.tension);
		}
		private void SendLaunchSkillData(global::Dpr.Contest.ADancePlayer player) {
			if (!CheckCanSendPacket(player))
				return;

			network.SendLaunchSkillDataToAll(player.PlayerIndex, elapsedTime, player.PlayerType == PlayerType.User ? userSkillDuration : player.SkillAnimDuration);
		}
		private bool CheckCanSendPacket(global::Dpr.Contest.ADancePlayer player) {
			if (!ContestWork.IsMultiMode)
				return false;

			if (player.PlayerType == PlayerType.User)
				return true;

			return network.IsHost();
		}
		public void ReceiveScore(global::Dpr.Contest.ScoreNetData scoreData) {
			// the 3-byte payload is copied once (ldrh + ldrb @01d8a110) and kept in a register across the calls
			ScoreData data = scoreData.data;
			// GetPlayerDanceDataByIndex inlined (@01d8a11c)
			PlayerDanceDataModel danceData = dataModel.GetPlayerDanceDataByIndex(data.playerIndex);
			int addScore = data.score - danceData.totalDanceScore;
			if (addScore < 0)
			{
				ContestUtils.EmitLog(string.Format("Player[{0}] : Add Score under 0!!", data.playerIndex));
				addScore = 0;
			}

			danceData.AddLiveScore(addScore);
			if (danceData.StackLiveScore > 0)
				EmitHeart(data.playerIndex, dancePlayerArray[data.playerIndex].PlayerType);

			TensionID prevTension = danceData.tension;
			danceData.ForceSetTension(data.tension);
			if (prevTension != danceData.tension)
				uiPlayerStatus.SetTensionID(data.playerIndex, danceData.tension, danceData.tension < prevTension);
		}
		public void ReceiveLaunchSkill(global::Dpr.Contest.LaunchSkillNetData launchSkillData) {
			// the payload is copied once (startElapsedTime / duration kept in x20 across ForceLaunchSkill @01d8a278)
			LaunchSkillData data = launchSkillData.data;
			ADancePlayer player = dancePlayerArray[data.playerIndex];
			float duration = data.duration - (elapsedTime - data.startElapsedTime);
			player.SetSkillAnimDuration(duration);
			player.ForceLaunchSkill(data.startElapsedTime);
			ContestUtils.EmitLog(string.Format("Force Launch Skill : StartTime : {0} - Finish : {1}", data.startElapsedTime, duration + elapsedTime));
		}
